    "event_date": "2026-09-16",
    "source_published_date": "2026-09-16",
    "ainoma_published_date": "2026-09-17",
    "ainoma_updated_date": "2026-09-22",
    "author": "AiNoma Tadqiqotlar Bo‘limi",
